-- Preserve the original two-column game/manual style window in native wxLua.
local wx=require('wx');local Document=require('Manual.Document');local Themes=require('Manual.Themes');local StyleManager={};
function StyleManager.show(parent,editor)
    local dialog=wx.wxDialog(parent,wx.wxID_ANY,'Manual Styles',wx.wxDefaultPosition,wx.wxSize(760,570),wx.wxDEFAULT_DIALOG_STYLE);require('Manual.Chrome').font(dialog,9);local outer=wx.wxBoxSizer(wx.wxVERTICAL);local columns=wx.wxBoxSizer(wx.wxHORIZONTAL);outer:Add(columns,1,wx.wxEXPAND+wx.wxALL,16);
    local left=wx.wxPanel(dialog,wx.wxID_ANY);local ls=wx.wxBoxSizer(wx.wxVERTICAL);left:SetSizer(ls);columns:Add(left,1,wx.wxEXPAND+wx.wxRIGHT,16);ls:Add(require('Manual.Chrome').heading(left,'Game styles · read-only',editor),0,wx.wxEXPAND+wx.wxBOTTOM,6);local game=wx.wxListBox(left,wx.wxID_ANY,wx.wxDefaultPosition,wx.wxSize(-1,220),editor.styles.names);ls:Add(game,1,wx.wxEXPAND);ls:Add(require('Manual.Chrome').heading(left,'Manual styles',editor),0,wx.wxEXPAND+wx.wxTOP+wx.wxBOTTOM,8);local manual=wx.wxListBox(left,wx.wxID_ANY,wx.wxDefaultPosition,wx.wxSize(-1,110));ls:Add(manual,0,wx.wxEXPAND);local actions=wx.wxBoxSizer(wx.wxHORIZONTAL);local create=wx.wxButton(left,wx.wxID_ANY,'New');local remove=wx.wxButton(left,wx.wxID_ANY,'Delete');actions:Add(create,0,wx.wxRIGHT,6);actions:Add(remove,0);ls:Add(actions,0,wx.wxTOP,6);
    local right=wx.wxPanel(dialog,wx.wxID_ANY);local rs=wx.wxBoxSizer(wx.wxVERTICAL);right:SetSizer(rs);columns:Add(right,1,wx.wxEXPAND);local fields={};
    for _,spec in ipairs({{'name','Name'},{'parent','Inherit from'},{'size','Font size (pt; blank = inherit)'},{'bold','Bold'},{'italic','Italic'},{'underline','Underline'}})do local key=spec[1];rs:Add(wx.wxStaticText(right,wx.wxID_ANY,spec[2]),0,wx.wxTOP+wx.wxBOTTOM,4);local control;
        if key=='parent' then control=wx.wxChoice(right,wx.wxID_ANY);elseif key=='bold' or key=='italic' or key=='underline' then control=wx.wxChoice(right,wx.wxID_ANY,wx.wxDefaultPosition,wx.wxSize(-1,26),{'Inherit','On','Off'});
        elseif key=='size' then control=wx.wxSpinCtrlDouble(right,wx.wxID_ANY,'',wx.wxDefaultPosition,wx.wxSize(-1,26),wx.wxSP_ARROW_KEYS,.1,1000,12,.1);control:SetDigits(1);
        else control=wx.wxTextCtrl(right,wx.wxID_ANY,'');end;fields[key]=control;rs:Add(control,0,wx.wxEXPAND);
    end
    local note=wx.wxStaticText(right,wx.wxID_ANY,'Game sizes inherit the text block. A fixed manual size overrides that size. Other style properties stay in the game.');note:Wrap(335);rs:Add(note,0,wx.wxTOP+wx.wxBOTTOM,10);local errorLabel=wx.wxStaticText(right,wx.wxID_ANY,'');rs:Add(errorLabel,0,wx.wxEXPAND+wx.wxBOTTOM,6);local save=wx.wxButton(right,wx.wxID_ANY,'Save manual style');rs:Add(save,0,wx.wxEXPAND);local close=wx.wxButton(dialog,wx.wxID_CANCEL,'Close');outer:Add(close,0,wx.wxALIGN_RIGHT+wx.wxALL,12);dialog:SetSizer(outer);local minimum=outer:GetMinSize();local client=dialog:GetClientSize();dialog:SetClientSize(wx.wxSize(math.max(client:GetWidth(),minimum:GetWidth()+8),math.max(client:GetHeight(),minimum:GetHeight()+8)));dialog:Layout();local editing;
    local function sizeText()local children=fields.size:GetChildren();for i=0,children:GetCount()-1 do local window=children:Item(i):GetData():DynamicCast('wxWindow');if window:GetClassInfo():GetClassName()=='wxTextCtrl' then return window:DynamicCast('wxTextCtrl'):GetValue();end;end;error('Native size input has no text control.');end
    local function fill(style)
        editing=style and style.name or nil;manual:Clear();for _,v in ipairs(editor.document.manualStyles)do manual:Append(v.name);end;if editing then manual:SetStringSelection(editing);end;fields.parent:Clear();for _,name in ipairs(editor.styleNames())do if name~='manual:'..tostring(editing) then fields.parent:Append(name);end;end
        fields.name:SetValue(style and style.name or '');fields.parent:SetStringSelection(style and style.parent or game:GetStringSelection()~='' and game:GetStringSelection() or editor.styles.names[1] or 'BASE');fields.size:SetValue(style and style.size and tostring(style.size) or '');for _,key in ipairs({'bold','italic','underline'})do fields[key]:SetSelection((not style or style[key]==nil) and 0 or style[key] and 1 or 2);end;errorLabel:SetLabel('');
    end
    create:Connect(wx.wxEVT_COMMAND_BUTTON_CLICKED,function()fill();end);game:Connect(wx.wxEVT_COMMAND_LISTBOX_SELECTED,function()if not editing then fields.parent:SetStringSelection(game:GetStringSelection());end;end);manual:Connect(wx.wxEVT_COMMAND_LISTBOX_SELECTED,function()for _,style in ipairs(editor.document.manualStyles)do if style.name==manual:GetStringSelection() then fill(style);break;end;end;end);
    local function referenced(key)
        local function scan(value)if rawtype(value)=='string' then return value==key or value:find(key,1,true)~=nil;elseif rawtype(value)=='table' then for k,v in pairs(value)do if tostring(k):sub(1,1)~='_' and scan(v) then return true;end;end;end;return false;end
        if scan(editor.document.settings) or scan(editor.document.contents) or scan(editor.document.pages) or scan(editor.document.masters) then return true;end;for _,style in ipairs(editor.document.manualStyles)do if style.parent==key then return true;end;end;return false;
    end
    remove:Connect(wx.wxEVT_COMMAND_BUTTON_CLICKED,function()if not editing then return;end;if referenced('manual:'..editing) then errorLabel:SetLabel('This style is still referenced. Change those references before deleting it.');errorLabel:Wrap(335);dialog:Layout();return;end;editor.change(function()for i,style in ipairs(editor.document.manualStyles)do if style.name==editing then table.remove(editor.document.manualStyles,i);break;end;end;end);fill();end);
    save:Connect(wx.wxEVT_COMMAND_BUTTON_CLICKED,function()
        local ok,message=pcall(function()local name=fields.name:GetValue():match('^%s*(.-)%s*$');assert(name~='','Enter a style name.');assert(not editing or editing==name,'Keep the existing name; create a new variant to use another name.');local variants=Document.copy(editor.document.manualStyles);for i=#variants,1,-1 do if variants[i].name==editing then table.remove(variants,i);elseif variants[i].name==name then error('That manual style already exists.');end;end
            local candidate={name=name,parent=fields.parent:GetStringSelection()};local size=sizeText();if size~='' then candidate.size=tonumber(size);assert(candidate.size and candidate.size>0,'Choose a positive font size.');end;for _,key in ipairs({'bold','italic','underline'})do local value=fields[key]:GetSelection();if value~=0 then candidate[key]=value==1;end;end;variants[#variants+1]=candidate;editor.styles.resolve('manual:'..name,variants,12);editor.change(function()editor.document.manualStyles=variants;end);fill(candidate);
        end);if not ok then errorLabel:SetLabel(tostring(message));errorLabel:Wrap(335);dialog:Layout();end;
    end);
    fill();Themes.apply(dialog,editor.theme);dialog:ShowModal();dialog:Destroy();
end
return StyleManager;
